# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KELAM İLMİNDE AKLÎ HÜKÜMLER VE VARLIK TÜRLERİ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">1. VÂCİBÜ\'L-VÜCÛD</text>\n  <text x="127" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Zorunlu Varlık — Allah)</text>\n  <text x="38" y="116" font-size="11" fill="#14532d">• Varlığı kendi zatındandır.</text>\n  <text x="38" y="138" font-size="11" fill="#14532d">• Yokluğu aklen düşünülemez.</text>\n  <text x="38" y="160" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kadîm\'dir:</tspan> Başlangıcı (ezelî)</text>\n  <text x="46" y="176" font-size="11" fill="#14532d">ve sonu (ebedî) yoktur.</text>\n  <text x="38" y="204" font-size="11" font-weight="bold" fill="#166534">Hiçbir şeye muhtaç değildir.</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. MÜMKÜNÜ\'L-VÜCÛD</text>\n  <text x="349" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">(Mümkün Varlık — Âlem)</text>\n  <text x="260" y="116" font-size="11" fill="#1e3a8a">• Varlığı ve yokluğu eşittir.</text>\n  <text x="260" y="138" font-size="11" fill="#1e3a8a">• Var olmak için Yaratıcıya</text>\n  <text x="268" y="154" font-size="11" fill="#1e3a8a">(müessire) muhtaçtır.</text>\n  <text x="260" y="176" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Hâdis\'tir:</tspan> Sonradan var</text>\n  <text x="268" y="192" font-size="11" fill="#1e3a8a">olmuştur, değişken ve fanidir.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">3. MÜMTENİÜ\'L-VÜCÛD</text>\n  <text x="572" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">(İmkânsız — Yokluk)</text>\n  <text x="483" y="116" font-size="11" fill="#7f1d1d">• Var olması aklen ve</text>\n  <text x="491" y="132" font-size="11" fill="#7f1d1d">mantıken imkânsız olandır.</text>\n  <text x="483" y="156" font-size="11" fill="#7f1d1d">• Örnek 1: Allah\'ın eşi veya</text>\n  <text x="491" y="172" font-size="11" fill="#7f1d1d">ortağının (şerîk) bulunması</text>\n  <text x="483" y="196" font-size="11" fill="#7f1d1d">• Örnek 2: Bir şeyin aynı anda</text>\n  <text x="491" y="212" font-size="11" fill="#7f1d1d">hem var hem yok olması</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KELAM İLMİNDE ALLAH - ÂLEM İLİŞKİSİ</text>\n  <rect x="30" y="48" width="280" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="170" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">ALLAH TEÂLÂ (Hâlık &amp; Kayyûm)</text>\n  <text x="45" y="98" font-size="12" fill="#78350f">• Âlemi yoktan var edendir (Yoktan yaratma).</text>\n  <text x="45" y="122" font-size="12" fill="#78350f">• Âleme aşkındır (Evrenin cinsinden değildir).</text>\n  <text x="45" y="146" font-size="12" fill="#78350f">• Her an yaratma ve yönetme hâlindedir</text>\n  <text x="55" y="164" font-size="11" font-weight="bold" fill="#b45309">(Rahman Suresi 29. Ayet).</text>\n  <text x="45" y="190" font-size="12" fill="#78350f">• Sünnetullah (tabiat kanunları) koymuştur.</text>\n\n  <line x1="310" y1="143" x2="380" y2="143" stroke="#0f172a" stroke-width="2.5"/>\n  <polygon points="380,137 392,143 380,149" fill="#0f172a"/>\n  <text x="350" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Yaratma &amp;</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Koruma</text>\n\n  <rect x="392" y="48" width="280" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="532" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">ÂLEM (Mahlûk &amp; Mâsivâ)</text>\n  <text x="407" y="98" font-size="12" fill="#0c4a6e">• Allah\'ın dışındaki tüm varlıklardır.</text>\n  <text x="407" y="122" font-size="12" fill="#0c4a6e">• Başlangıcı vardır (Hâdis) ve sonludur.</text>\n  <text x="407" y="146" font-size="12" fill="#0c4a6e">• Var olmak ve varlığını sürdürmek için</text>\n  <text x="417" y="164" font-size="11" font-weight="bold" fill="#0369a1">her an Allah\'a muhtaçtır (Fatır 15).</text>\n  <text x="407" y="190" font-size="12" fill="#0c4a6e">• Yaratıcıya işaret eden kevni delildir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KELAM KOZMOLOJİSİNDE MADDENİN YAPISI: CEVHER, CİSİM VE ARAZ</text>\n  <rect x="25" y="48" width="205" height="130" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. CEVHER (Cevher-i Ferd)</text>\n  <text x="38" y="94" font-size="11" fill="#1e3a8a">• Boşlukta yer kaplayan ve</text>\n  <text x="46" y="110" font-size="11" font-weight="bold" fill="#1d4ed8">bölünemeyen en küçük parça</text>\n  <text x="38" y="132" font-size="11" fill="#1e3a8a">• Kendi başına var olabilir,</text>\n  <text x="46" y="148" font-size="11" fill="#1e3a8a">arazları üzerinde taşır.</text>\n\n  <rect x="247" y="48" width="205" height="130" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. CİSİM (Mürekkep Yapı)</text>\n  <text x="260" y="94" font-size="11" fill="#14532d">• En az iki veya daha fazla</text>\n  <text x="268" y="110" font-size="11" font-weight="bold" fill="#15803d">cevherin birleşmesiyle</text>\n  <text x="268" y="126" font-size="11" fill="#14532d">oluşan üç boyutlu (en, boy,</text>\n  <text x="268" y="142" font-size="11" fill="#14532d">derinlik) maddi varlık.</text>\n\n  <rect x="470" y="48" width="205" height="130" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="572" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. ARAZ (Geçici Nitelik)</text>\n  <text x="483" y="94" font-size="11" fill="#581c87">• Kendi başına var olamayan,</text>\n  <text x="491" y="110" font-size="11" fill="#581c87">cevhere muhtaç özellikler</text>\n  <text x="483" y="132" font-size="11" font-weight="bold" fill="#6b21a8">• Renk, tat, koku, sıcaklık,</text>\n  <text x="491" y="148" font-size="11" font-weight="bold" fill="#6b21a8">hareket ve sükûn (durağanlık)</text>\n\n  <rect x="25" y="192" width="650" height="52" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="213" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">HUDÛS DELİLİNİN MANTIK ZİNCİRİ</text>\n  <text x="350" y="232" text-anchor="middle" font-size="11" fill="#78350f">Arazlar sürekli değişir (Hâdistir) → Cevherler arazdan ayrı kalmaz → Âlem hâdistir → Her hâdisin bir Muhdisi (Yaratıcısı) vardır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
